DROP TABLE IF EXISTS `wp_icl_translation_status`;
CREATE TABLE `wp_icl_translation_status` (
  `rid` bigint NOT NULL AUTO_INCREMENT,
  `translation_id` bigint NOT NULL,
  `status` tinyint NOT NULL,
