(395,	65,	'_hp_destination_title',	'field_6afd49de3d056'),
(396,	65,	'hp_destination_destination',	'नयाँ ठाउँहरू पत्ता लगाउनुहोस्, विश्वभरका मानिसहरूसँग भेटघाट गर्नुहोस् र आतिथ्य क्षेत्रमा व्यावहारिक अनुभव हासिल गर्नुहोस्।'),
